  LanguageConfig_BonusRuleContent_PontosActivity_CN = {
    Text = "1, Belirli Uyandırıcılara veya Kader Çarklarına sahip Koruyucular (sahaya çıkmaları gerekmez) \"Yüksek Ev Avı\" sahne görevi ödüllerindeki \"Taze \"Av\"\", \"Devasa \"Av\"\" ve \"İlksel \"Av\"\" için ek düşüş bonusu elde edebilir. Ayrıntılı bonuslar aşağıdaki gibidir:\n·Uyandırıcı \"Pontos\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n·SSR Kader Çarkı \"Canlı Kafes\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n·SR Kader Çarkı \"Başıboş Pusula\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n2, Farklı Uyandırıcı veya Kader Çarklarının \"Etkinlik Bonusu\" yığılarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_RykerActivity_CN = {
    Text = "1. Belirli Uyananlar’a veya Kader Çarkları’na sahip olan Muhafız(sahada olmaları gerekmez), \"Mehtap masalları\" seviye görev ödüllerinde(yeniden canlandırmalar dahil) \"Karar Fişleri\" için ek düşüş bonusu elde edebilir. Belirli bonuslar şöyledir:\nUyanan \"Ryker\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSSR Kader Çarkı \"Şans Saati\": Yığılma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSR Kader Çarkı \"Kader Ruleti\": Yığılma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyananlar veya Kader Çarkları’ndan gelen \"fiş bonusları\" birikmeli şekilde hesaplanır."
  },
  LanguageConfig_BonusRuleContent_SalvadorActivity_CN = {
    Text = "1. Belirli Uyandırıcılara veya Kader Çarklarına sahip olan Koruyucu (sahada olmaları gerekmez), \"Kilise Yolu\" seviyesinin görev ödüllerinde (yeniden canlandırma dahil) ek \"Hayır Kuponu\" düşürme bonusu kazanabilir. Spesifik bonuslar aşağıdaki gibidir:\nUyandırıcı \"Salvador\": Aydınlanma 0/1/2/3 ve üzeri, bonus 20%/30%/40%/50%\nSSR Kader Çarkı \"Kutsal Söz Levhası\": Yükseliş 0/1/2/3 ve üzeri, bonus 20%/30%/40%/50%\nSR Kader Çarkı \"Aynadaki Adam\": Yükseliş 0/1/2/3 ve üzeri, bonus 20%/30%/40%/50%\n2. Farklı Uyandırıcıların veya Kader Çarklarının \"Kupon Bonusları\" birikerek hesaplanır."
  },
  LanguageConfig_BonusRuleContent_SayaActivity_CN = {
    Text = "1, Koruyucu'nun belirli bir Uyandırıcı veya Kader Çarkı'na sahip olması(savaşa çıkması gerekmez) \"Karanlık Oda Notları\" Sahnesi görev ödüllerindeki \"Soluk Pul Tozu\", \"Kırmızı Pul Tozu\" ve \"Parlak Pul Tozu\" için ekstra düşme bonusu sağlar. Ayrıntılı bonuslar aşağıdaki gibidir:\n·Uyandırıcı \"Saya\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n·SSR Kader Çarkı \"Dünya kokuya dönüşsün\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n·SR Kader Çarkı \"Çamurdaki peri masalı\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n2, Farklı Uyandırıcı veya Kader Çarkı'nın \"Etkinlik Bonusu\" birikimli olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_SorelActivity_CN = {
    Text = "1. Belirli bir Uyanan’a veya Kader Çarkı’na sahip olan Muhafız(sahaya sürülmeleri gerekmez), \"Gül Anıları\" seviye görev ödüllerinde(yeniden oynanışlar dahil) \"Ruhani Kuş Tüyü Yelpazesi\" için ek düşüş bonusu sağlayabilir. Belirli bonuslar şöyledir:\nUyanan \"Sorel\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSSR Kader Çarkı \"Gül Adına\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSR Kader Çarkı \"Milyon Sevgi Dolu Bakış\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyananlar veya Kader Çarkları’ndan gelen \"Yelpaze Bonusu\" toplamalı(eklemeli) olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_StElmosFireActivity_CN = {
    Text = "1. Belirli bir Uyanan veya Kader Çarkı’na sahip Muhafız(Savaşa Sokulmasına gerek olmadan), \"Derin Denizde Kayıp\" sahnesi görev ödülü \"Sinyal Sancağı\" için ek Düşüş Oranı Güçlendirmesi(yeniden canlandırmalar dâhil) sağlayabilir. Özel Güçlendirmeler şöyledir:\nUyanan \"Corposant\": Aydınlanma 0/1/2/3 ve üzeri, Güçlendirme %20/%30/%40/%50\nSSR Kader Çarkı \"Kutsal Ateşin Rehberi\": Yükseliş 0/1/2/3 ve üzeri, Güçlendirme %20/%30/%40/%50\nSR Kader Çarkı \"Deniz Kılavuzu\": Yükseliş 0/1/2/3 ve üzeri, Güçlendirme %20/%30/%40/%50\n2. Farklı Uyananlar veya Kader Çarkları’ndan gelen \"Etkinlik Bonusu\" istiflenebilir şekilde hesaplanır."
  },
  LanguageConfig_BonusRuleContent_Summer2Activity_CN = {
    Text = "1. “Tatil Seyahat Kayıtları” içindeki “Gelişmiş Seyahat Kayıtları”nı açarak “Sahil Özel Kabukları” için ek düşüş bonusu (Yeniden Canlandırma dâhil) elde edersiniz; belirli bonuslar şöyledir:\n“Gelişmiş Seyahat Kayıtları” açıldıktan sonra: Bonus %100."
  },
  LanguageConfig_BonusRuleContent_TaisuiActivity_CN = {
    Text = "1. Belirli Uyandırıcılara veya Kader Çarklarına sahip Koruyucular (konuşlandırılmaları gerekmez), \"Yer Tutucu Metin\" Sahne görevi ödüllerindeki \"Yer Tutucu Metin\" için ek düşürme bonusu elde edebilir. Belirli bonuslar aşağıdaki gibidir:\n·Uyandırıcı \"Taisui\": Aydınlanma 0/1/2/3 veya üzeri, bonus %20/%30/%40/%50.\n·SSR Kader Çarkı \"Yer Tutucu Metin\": Yükseliş 0/1/2/3 veya üzeri, bonus %20/%30/%40/%50.\n·SR Kader Çarkı \"Yer Tutucu Metin\": Yükseliş 0/1/2/3 veya üzeri, bonus %20/%30/%40/%50.\n2. Farklı Uyandırıcılardan veya Kader Çarklarından elde edilen \"Etkinlik Bonusu\" kümülatif olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_TawilActivity_CN = {
    Text = "1. Belirli Uyananlara veya Kader Çarkları’na sahip olan Muhafız(sahada bulunmaları gerekmez), \"Son Sınav\" seviye görev ödüllerinde(yeniden canlandırmalar dâhil) yer alan \"Son Gösterge\" için ek düşüş bonusu elde edebilir. Özel bonuslar şöyledir:\nUyanan \"Tawil\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSSR Kader Çarkı \"Görünmez Çark\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSR Kader Çarkı \"Hakikat Kapısı\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyananlar veya Kader Çarkları’ndan gelen \"Son Gösterge\" bonusları birikimli olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_ThaisActivity_CN = {
    Text = "1. Belirli Uyandıranlara veya Kader Çarkları’na sahip olan(sahada olmaları gerekmez) Koruyucular, \"Kaotik Arzu\" seviyesinin(yeniden canlandırmalar dâhil) görev ödüllerinde \"Bereket Çekirdeği\" için ek düşüş bonusu sağlayabilir. Özel bonuslar aşağıdaki gibidir:\nUyandıran \"Thais\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSSR Kader Çarkı \"Merhametli Beslenme\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSR Kader Çarkı \"Veda Öpücüğü\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyandıranlar veya Kader Çarkları’ndan gelen \"Açgözlülük Bonusu\" toplamsal olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_TuluActivity_CN = {
    Text = "1. Belirli bir Uyanan veya Kader Çarkı’na sahip Muhafız(sahaya sürülmesi gerekmez), \"Aequor Bakışı\" seviye görev ödüllerinde yer alan \"Yorgun Düşünceler\", \"Kederli Düşünceler\" ve \"Neşeli Düşünceler\" için ek düşüş bonusları(yeniden ortaya çıkışlar dâhil) sağlayabilir. Özel bonuslar şöyledir:\nUyanan \"Tulu\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSSR Kader Çarkı \"Tanrı Kralın İlahisi\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\nSR Kader Çarkı \"Mavi Taş Tahtı\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyananlar veya Kader Çarkları’ndan gelen \"Düşünce Bonusları\" toplamalı olarak hesaplanır."
  },
  LanguageConfig_BonusRuleContent_WandaActivity_CN = {
    Text = "1. Belirli Uyandırıcılar'a veya Kader Çarkları'na sahip olan Koruyucular(sahip olmak yeterlidir, sahaya sürülmeleri gerekmez), \"Alevlerin Şöleni\" Aşama ödüllerinde(Yeniden Canlandırma dâhil) \"Orijinal Kaval Kemiği\", \"Tornoceras\" ve \"Sarmal Kalıntılar\" için ek düşüş bonusları kazanabilir. Özel bonuslar şöyledir:\n·Uyandırıcı \"Wanda\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n·SSR Kader Çarkı \"Kraliçenin Fermanı\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n·SR Kader Çarkı \"Isarawu'nun Bakışı\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50\n2. Farklı Uyandırıcılar veya Kader Çarkları'ndan gelen \"Nadir Bonus\" istiflenerek hesaplanır."
  },
  LanguageConfig_BonusRuleContent_XuActivity_CN = {
    Text = "1. Belirli Uyananlara veya Kader Çarklarına sahip olan Koruyucular(savaşa sokulmaları gerekmez), \"Obsidyen Anaerkil\" safha görev ödüllerinde \"Armut Şurubu Şekeri\" için ek düşüş bonusları alabilir; belirli bonuslar şöyledir:\nUyanan \"Xu\": Aydınlanma 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\nSSR Kader Çarkı \"Boş Pişmanlıklar\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\nSR Kader Çarkı \"Magnolia’nın Cazibesi\": Yükseliş 0/1/2/3 ve üzeri, bonus %20/%30/%40/%50.\n2. Farklı Uyananların veya Kader Çarklarının \"etkinlik bonusları\" toplamalı biçimde hesaplanır."
