  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "Bağışladığın her damla Gümüş Çekirdek Özü kıymetlidir. Çözünme Araştırması ve kampüs inşasında kullanılacak, unutuşa karşı verdiğimiz mücadeleye katkıda bulunacaktır.\nGümüş Anahtar Bize Yol Göstersin."
  },
  LanguageConfig_DiamondDonateTipContent_CN = {
    Text = "<Title:Bağış Kuralları>\n\"Gümüş Çekirdek Özü Bağışı\" yoluyla harcanan Gümüş Çekirdek Özü, toplam bağış değerine dâhil edilir.\nBir \"Uyanış\" sırasında yetersiz Gümüş nedeniyle doğrudan bağışlanan Kaynak Sıvısı da sayılacaktır.\n<Title:Ödül Kuralları>\nBağışlanan her bir damla Kaynak Sıvısı için 1 Katkı Puanı alırsınız.\nHer 2.500 Katkı Puanı size 1 Özel Ödül kazandırır.\nHer 20 Özel Ödül, tam bir döngü oluşturur.\nHer döngünün toplam ödülleri şunlardır: \"Arıtılmış İlksel Ruh Çekirdeği\" ×1, \"Gnosis Özü\" ×3, \"Eterik Taş\" ×6, \"Anı Tüy Kalemi\" ×800, \"Biçimsiz Olanın Hediye Kartı\" ×100, \"Bin Yüz Mührü\" ×5.000, \"Gül Senedi\" ×50.000.000.\n"
  },
