  LanguageConfig_EnergyMonthCardRuleContent_CN = {
    Text = "[In-Sheath Supply Introduction]\nHer Kılıf İçi İkmal satın alışında, anında 680 Gümüş ve 30 günlük Kılıf İçi İkmal süresi elde edersin.\nKılıf İçi İkmal süresi boyunca, her gün postandan 300 Menofin ve 30 Anı Tüy Kalemi alabilirsin; bu ödüller her sabah 9:00’da [GMT+8] sıfırlanır.\n\n[Notes]\nToplam Kılıf İçi İkmal süresi yalnızca kalan süre ≤180 gün olduğunda yeniden satın alırsan uzatılır.\nKalan Kılıf İçi İkmal süresi >180 gün ise yeniden satın alamazsın.\nÖzel nedenlerle mükerrer satın alma gerçekleşirse, toplam süreye eklenmez ve 680 Gümüş doğrudan iade edilir.\nKılıf İçi İkmal süresi boyunca alınmamış Menofin ve Anı Tüy Kalemleri iade edilmez."
