  LanguageConfig_LotteryNormalReward_CN = {
    Text = "Sıradan Eşyalar"
  },
  LanguageConfig_LotteryPhoneticDialogue10_CN = {
    Text = "Daha dindar ol, daha çok kurban sun... İlahi Diyar senin saygı duruşunu izler ve bir gün sana karşılık verecektir."
  },
  LanguageConfig_LotteryPhoneticDialogue11_CN = {
    Text = "En sıradan ruh bile bu dizelerle sarsılabilir... Bu çiçek senin için açıyor!"
  },
  LanguageConfig_LotteryPhoneticDialogue12_CN = {
    Text = "Şiirler kendi duygularını taşır, tıpkı çiçeklerin kendi anlamlarını taşıması gibi. Bu da senin için."
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Bak ve gör, sonsuza dek savaşacağım."
  },
  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "Zaferime tanık olmaya mı geldin?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "İstediğin kadar çırpın, canım. Öğretmenin seni başından okşamasını ister misin?"
  },
  LanguageConfig_LotteryPhoneticDialogue16_CN = {
    Text = "Elinde bunun gibi hurdalardan başka bir şey yokken, sence neyi kurtarabilirsin?"
  },
  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "Ah, epey şanslıymışsınız, sevgili müşterim. Bir kez daha denemek ister misiniz?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "Bir kez daha göz atmak ister misiniz? Dükkânımda stokta çok daha kıymetli eşyalar var."
  },
  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "Bu rapor epey leziz. İkram için minnettarım."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Şefkatin için minnettarım, sevgili."
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Mm, alıyorum. Başka bir şey?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Hediyen için teşekkür ederim. Lütfen karşılık olarak bunları kabul et."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "Bazı nadir malzemeler buldum. Umarım işine yararlar."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "Basit bir meze, afiyet olsun."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "Bu yemek bizzat Hazretleri’nin elleriyle hazırlanmıştır. Damak zevkinize hitap etmesini umarız."
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "Tekniklere ve kurallara fazlaca kapılma."
  },
  LanguageConfig_LotteryPhoneticDialogue26_CN = {
    Text = "Akıl yalnızca taklit etmeyi öğretir, oysa delilik yaratmana izin verir."
  },
  LanguageConfig_LotteryPhoneticDialogue27_CN = {
    Text = "İnsanlar delilikten korkar, çünkü Gerçek’ten tek bir parıltı bile görmemişlerdir."
  },
  LanguageConfig_LotteryPhoneticDialogue28_CN = {
    Text = "Gördün mü? Gerçek dünyayı!"
  },
  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "Gerçek renkleri gördüm. Ne muhteşemdi."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "Ah, ne muazzam bir talih! Ona iyi bak."
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "Delilik ve saçmalık, gerçekliğin güzelliği ve sanatın güzelliğidir!"
  },
  LanguageConfig_LotteryPhoneticDialogue31_CN = {
    Text = "Karanlık. Leke kalır. Devam et, günahlarını mutlaka yıkamalısın."
  },
  LanguageConfig_LotteryPhoneticDialogue32_CN = {
    Text = "Ne kadar güzel, saf ruhunu görüyorum..."
  },
  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = "Hey, Koruyucu! Her şey tıpatıp aynı şekilde yaşansa bile, yine de beni kurtarırdın, değil mi?\n...O zaman rahat uyuyabilirim. Te-öhöm, yani, teşekkür ederim."
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "Son zamanlarda sürekli geçmişi rüyamda görüyorum. Aklımı kaçıracağım. Umarım bu işe yarar."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "İlahi Ana, Lemuria uğruna soylu bir Kurban verdi ve biz, onun huzuru için her şeyi Borsa’ya koymaya razıyız."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "İlahi Ana’ya sunduğun Ziyaret için teşekkürler; umarım bu, ona huzurlu bir gece uykusu getirir."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = "Bu rüya sonsuza dek dönüp duracak, ve sen...\nŞükret—onun bir parçası olmana izin vereceğim."
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "Hiç rüyalarımın neye benzediğini gördün mü? Öyle bir pislik ki, özüne dek çürümüş..."
  },
  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "Dünyevi varlıklar ne kadar da gereksiz. Bir dileğin varsa, neden onu doğrudan bana fısıldamıyorsun...?"
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "Gerçekten altın vurdun, genç olan! Mağazamda ne varsa hepsi kadim bir Kalıntı!"
  },
  LanguageConfig_LotteryPhoneticDialogue40_CN = {
    Text = "Kendini Uzak Doğu'nun ıssız harabeleri arasında bulursan, dikkat et—öyle rastgele tapınma sunma. Hayaletler mi, iblisler mi? Hah... anmaya bile değmezler."
  },
  LanguageConfig_LotteryPhoneticDialogue41_CN = {
    Text = "Coalsie, en iyisi!"
  },
  LanguageConfig_LotteryPhoneticDialogue42_CN = {
    Text = "Kömürcük, harika!"
  },
  LanguageConfig_LotteryPhoneticDialogue43_CN = {
    Text = "Pırıl Pırıl! Senin için, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue44_CN = {
    Text = "Arkadaş, beğen! Vortice, Coalsie, Borsa!"
  },
  LanguageConfig_LotteryPhoneticDialogue45_CN = {
    Text = "Deniz kabuğu, ne kadar güzel! Vortice, topla! Coalsie, ödüller!"
  },
  LanguageConfig_LotteryPhoneticDialogue46_CN = {
    Text = "Vortice, sevdi! Teşekkürler, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue47_CN = {
    Text = "Doğru... Kader tarafından terk edilmiş olan sen, şimdi onun kafesini paramparça et!"
  },
  LanguageConfig_LotteryPhoneticDialogue48_CN = {
    Text = "Ah, Kaderin küçük ve acımasız bir şakası."
  },
  LanguageConfig_LotteryPhoneticDialogue49_CN = {
    Text = "Üremek, büyümek; bunların hepsi aşkla yakından ilgilidir."
  },
  LanguageConfig_LotteryPhoneticDialogue4_CN = {
    Text = "Böylesine güçlü bir Sihir tarafından seçilmişsin... Yoksa sen o Efsanevi Seçilmiş Kişi misin?"
  },
  LanguageConfig_LotteryPhoneticDialogue50_CN = {
    Text = "O dünyaya yalnız başıma ulaştığımda, biri bana pek çok, pek çok şey öğretti ve bugüne kadar da öğrenmeye devam ediyorum."
  },
  LanguageConfig_LotteryPhoneticDialogue51_CN = {
