  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "\"Egzersiz Sertifikaları\"nı, diğer Koruyucular tarafından kurulmuş savunma takımlarına meydan okumak için tüketebilirsin. Meydan okuma başarılı olursa, sıralaman yükselir. Aynı zamanda kendi savunma takımını da dikkatle düzenlemen gerekir; aksi takdirde, diğer Koruyucular tarafından başarıyla meydan okunabilir ve rütben düşebilir. Rütbe ne kadar yüksekse, saat başına o kadar fazla \"Egzersiz Rozeti\" elde edilir. \"Egzersiz Sertifikaları\" zamanla kendiliğinden kazanılır. \"Egzersiz Rozetleri\", Borsa Dükkanı'nda Gül Senetleri, Gnosis İksirleri ve diğer eşyalarla takas edilebilir."
