  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "\"Telaşlı Gökyüzü Hattı\"nda aşağıdaki kurallara sahip bir Seviye Telafisi mekaniği bulunmaktadır:\nSoruşturma ekibindeki seviyesi 60’ın altında olan Uyananlar, bu mücadele için seviye 60’a telafi edilir.\nSoruşturma ekibindeki beceri seviyesi 5’in altında olan Uyananlar, bu mücadele için seviye 5’e telafi edilir.\nSoruşturma ekibindeki \"Delilik Alameti\" seviyesi 6’nın altında olan Uyananlar, bu mücadele için seviye 6’ya telafi edilir.\nSoruşturma ekibindeki \"Ruh Dövme Yeteneği\" seviyesi 5’in altında olan Uyananlar, bu mücadele için seviye 5’e telafi edilir.\nMuhafızın seviyesi 60’ın altındaysa, bu mücadele için seviye 60’a telafi edilir."
  },
