  LanguageConfig_RailWayStageCrazyMileExpGetDescV2_CN = {
    Text = "Bu Operasyondan en fazla {s1} \"VIP Puanları\" kazanılabilir.\n{s3} kez \"Acil Gnosis\" kullanıldı; şu ana kadar {s2} \"VIP Puanları\" kazanıldı.\n  ·Birinci Aşama: Elit/Patron'u yenerek \"VIP Puanları\" ×25/75 kazan\n  ·İkinci Aşama: Elit/Patron'u yenerek \"VIP Puanları\" ×50/150 kazan\n  ·Üçüncü Aşama: Elit/Patron'u yenerek \"VIP Puanları\" ×75/225 kazan\n  ·Zor/Delilik Zorluğu'nda kazanılan \"VIP Puanları\" 150%/400% artar.\n  ·Delilik Zorluğu Dördüncü Aşama Patronunu yenerek ek olarak \"VIP Puanları\" × 1500 kazanılır.\n  ·Her 1 \"Acil Gnosis\" kullanımında \"VIP Puanları\" %20 azalır."
