  LanguageConfig_RailWayStageCrazyMileExpGetDesc_CN = {
    Text = "Bu operasyon için mevcut maksimum VIP Puanı: {s1}. \nKullanılan Acil Gnosis: {s3}. Şu ana kadar kazanılan: {s2} VIP Puanı. \n ·Aşama 1: Elit/Boss zaferi 25/75 VIP Puanı verir. \n ·Aşama 2: Elit/Boss zaferi 50/150 VIP Puanı verir. \n ·Aşama 3: Elit/Boss zaferi 75/225 VIP Puanı verir. \n ·Zor/Delilik zorluğu kazanılan VIP Puanlarını %150/%400 artırır. \n ·Her Acil Gnosis kullanımı VIP Puanlarını %20 azaltır."
  },
  LanguageConfig_RailWayStageCrazyNowDescV2_CN = {
    Text = "Delilik Zorluğu 4 aşamaya sahiptir; ilk 3 aşamada her aşamada 6 savaş bulunur. 4. aşamada doğrudan son Patrona meydan okunur.\nŞu anda {s1}. aşama - {s2}. savaşa ulaşıldı."
  },
  LanguageConfig_RailWayStageCrazyNowDesc_CN = {
    Text = "Her meydan okuma 3 Aşama içerir ve her aşamada 6 Savaş vardır.\nŞu anda {s1}. Aşama - {s2}. Savaş’tasın."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Aşama Ödülleri>\nİlk Aşama: Eliti/Boss’u yenerek \"VIP Puanı\" ×25/75 kazan\nİkinci Aşama: Eliti/Boss’u yenerek \"VIP Puanı\" ×50/150 kazan\nÜçüncü Aşama: Eliti/Boss’u yenerek \"VIP Puanı\" ×75/225 kazan\n<Title:Başlangıç Hatıraları>\nBaşlangıçta \"Küçük N’nin Tertemiz Kamerası\"nı kazan.\n<OrangeQuality:Golden Uyumu>: \"Arithmetica Uyumu\" artık yalnızca Arithmetica Maliyetini 1 artırır. Her %1 Hasar Güçlendirmesi, Gizem Araştırması Derinliğini %1 artırır.\n<RedQuality:Gidiş Geliş Yorgunluğu>: Savaşta iyileştirme etkileri -%50."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Özel Kurallar>\nZorluk seviyesi ne kadar yüksekse, o kadar fazla VIP Puanı kazanırsın. Üç Fazın hepsini tamamlarsan, VIP Puanı +%150.\n<Title:Başlangıç Kalıntıları>\nBaşlangıçta “Küçük N’nin Eski Kamerası”nı kazan.\n<OrangeQuality:Altın Uyumu>: “Arithmetica Uyumu” artık Arithmetica Maliyeti’ni yalnızca 1 artırır. Her %1 Hasar Güçlendirmesi, Okült Araştırma Derinliği’ni %1 artırır.\n<OrangeQuality:Boyutsal Armağan>: Başlangıçta 1 rastgele Boyutsal Kalıntı kazan. El Sınırı +1.\n<RedQuality:Gidiş Geliş Yorgunluğu>: Savaşta İyileştirme -%50.\n<RedQuality:Hareket Sarhoşluğu>: Savaşa -%50 Aliemus/Keyflare ile başla."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Özel Meydan Okuma>\nDelilik Zorluğunda üçüncü aşama tamamlandıktan sonra ek olarak dördüncü aşama son Patronu \"Tawil\"e meydan okunur.\n<Title:Sahne Ödülleri>\nMeydan okumanın zorluğu arttıkça daha fazla \"VIP Puanları\" kazanılır. Üç aşama tamamlandığında kazanılan \"VIP Puanları\" %400 artar.\nSon Patron \"Tawil\" yenildikten sonra ek olarak \"VIP Puanları\" × 1500 kazanılır.\n<Title:Başlangıç Kalıntıları>\nOperasyon başladığında \"Küçük N'nin Kaotik Kamerası\" Kalıntısı kazanılır.\n·<OrangeQuality:Altın Uyum>: \"Arithmetica Uyumu\"nun sağladığı Arithmetica artış etkisi en fazla 1 puan olur; her %1 Hasar Güçlendirmesine sahip olunduğunda Okült Araştırma etkisi %1 artar.\n·<OrangeQuality:Boyutsal Armağan>: Keşif başladığında rastgele 1 Boyutsal İmge Kalıntısı kazanılır ve Maksimum El Boyutu 2 artar.\n·<OrangeQuality:Mübarek Ritüel>: Birinci ve ikinci aşama Patronunu yenme ödülü, rastgele Mübarek Kalıntılar arasından 3'ten 1 seçimine dönüşür.\n·<RedQuality:Yolculuk Yorgunluğu>: Savaş sırasında tüm Can iyileştirme etkileri %50 azalır.\n·<RedQuality:Hareket Vertigosu>: Savaş başladığında tüm Uyandırıcıların mevcut Aliemus ve S-Enerjisi %50 azalır.\n·<RedQuality:Ebedî Gece Rayı>: Keşif başladığında tüm Uyandırıcıların Temel Aliemus ve S-Enerjisi üst sınırı %50 artar."
