  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "[A Gift of Kindness] düğümünde desteye 1 [Masumun Dönüş Hediyesi] ekle — Arithmetica Maliyeti 1, en az Aliemus’a sahip Uyanık’a 30 Aliemus ver, Tüket."
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "\"Delilik Yolu\" Etkinliğinde, bir Uyandırıcı seçerek şizofrenik hale getirin; başlangıçtaki 4 Komut Kartını kaybeder. Ardından ileriye giden yol belirecek ve bir Altın Kalıntı elde etmenize olanak tanıyacaktır (3 seçenek, 1 tanesini seçin). Kaybedilen Komut Kartlarını sonraki dört \"Bilinç Parçası\" etkinliğinde kademeli olarak geri kazanabilirsiniz. Geri kazanılan Komut Kartları doğrudan benzersiz bir <EnsembleKeywords:\"Topluluk\"> Mühürüne sahip olacaktır."
  },
  LanguageConfig_Resonance_Group_Desc_2_CN = {
    Text = "[Unfinished Wax Sculpture] düğümünde, 1 kart seç ve Arithmetica Maliyetini 1 azalt."
  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "[Strange Pustule] düğümünde desteye bir [Mutasyona Uğramış Kalp] ekle. Arithmetica Maliyeti: 0. Oynandığında, elindeki tüm kartları at ve atılan kart sayısı +1 kadar kart çek. Tüket."
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "[Honey Mead] düğümünde desteye bir [Bal Şarabı] kartı ekle — Arithmetica Maliyeti 1, 1 yığın Geçici Bariyer kazan, Tüket."
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "“Müptela” ve sonrasındaki sahnelerdeki “Vekil’in Ayini” düğümünde, “İlahi Uzuv” etkisini kazan—tur sonunda, takımının Maksimum Canının %10’una eşit hasarı ön sıradaki düşmana ver.\nDesteğine bir “Elçinin Hükmü” ekle—0 Arithmetica Maliyeti, oynandığında mevcut Canın %10’unu tüketir, “İlahi Uzuv”un arka sıradaki düşmanlara 3x Hasar, bir Reis Savaşı sırasında ise 10x Hasar vermesine neden olur. Tüket."
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "\"Bembeyaz Yelkenler\"de, destesine bir \"Ütopya Perdesi\" kartı ekle. 1 Arithmetica Maliyeti. Mevcut sahipliğinden 3 farklı Posse kartını gör, içlerinden 1’ini Posse bekleme süresini tetiklemeden derhal serbest bırakmak için seç. Reis Savaşlarında fazladan bir kez daha kullanılabilir. Tüketilir."
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "Keşfin başlangıç noktasının yakınlarında, özel bir Rezonans Olayıyla karşılaşacaksın— <TutorialHighlight:Besleyici Ana>. Özel <TutorialHighlight:Doğum> Lütfu’nu elde etmek için bir Komut Kartı seç, ancak bunun karşılığında rastgele 3 Semptom kartı da alırsın.\n<TutorialHighlight:Doğum> Lütfu: Bu karta Elde Tut özelliği verir. Tur sonunda hâlâ Elde ise, bu kartın Tükenir ve Elde Tut özelliklerine sahip ek bir Temel Kopyasını kazanırsın."
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "Başlangıç Noktası yakınında [Giriş Töreni] adlı Özel bir Rezonans Olayı bulunabilir ve destenize [Kutup Alacakaranlığı] ekler.\n[Kutup Alacakaranlığı]: Çekme Destenizden veya Atılmış Kart Destenizden 1 Komut Kartı seçin, elinize alın ve Arithmetica Maliyetini 0'a düşürün. (Tek kullanımlık, ardından Tükenir.)"
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "Keşif başlangıç noktasının yakınında, özel bir Rezonans olayıyla karşılaşacaksın —[弥萨格学生证]; [Kutup Alacakaranlığı] desteğine eklenir ve sekizinci bölümdeki tüm güçlendirmeleri miras alır."
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "Başlangıç Kalıntısı \"Keşif Ekibi\" kazan: 30 Keşif Ekibi üyesiyle başla. Savaş başlangıcında desteye 5 \"Şüphe\" kartı yerleştir. \"Şüphe\": Oynandığında, farklı sayıda üye tüketerek farklı efektler tetikler.\nKeşif sırasında sürekli olarak \"Şüphe\" ikilemiyle karşılaşacak ve ekip üyeleri arasında kayıplar yaşayacaksın. Bir Temas Noktasına Erişim, kurtarma şansı sağlar. Sonunda güvenli tahliye gerçekleştiğinde, kalan Keşif Ekibi üyelerinin sayısına göre \"Kurtarma Madalyası\" kazanırsın. Ne kadar çok kişi tahliye edilirse, \"Kurtarma Madalyası\" o kadar güçlü olur."
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "Keşfin başında, başlangıç Kalıntısı \"<color=#FFFFFF>Horla'nın Kalemi ve Mürekkebi</color>\"ni kazan: Savaş sonrası, 1 yığın \"<color=#FFFFFF>Kalem ve Mürekkep</color>\" kazan. \"<color=#FFFFFF>Kalem ve Mürekkep</color>\" 2 yığına ulaştığında, tüketilir ve destene rastgele 1 \"<color=#FFFFFF>İmge</color>\" kartı yerleştirilir.\nÖzel Rezonans Etkinliği [Spring's Gift] sırasında, \"<color=#FFFFFF>Dize Yarat</color>\"ı seçebilirsin: 3 \"<color=#FFFFFF>İmge</color>\" kartı seç ve Horla’dan senin için bir \"<color=#FFFFFF>Dize</color>\" işlemesini iste."
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "Rezonans etkinliği \"Yapımcının Efsanesi\"nde, \"Ortağın Yardımını Ara\" seçeneği, 3 İleri Dua arasından 1 tane elde etmeni sağlar."
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "Keşfin başlangıcında desteye 3 güçlendirme kartı ekle: <DerivativeCardKeywords_57:\"Sıcak Bir Aile\">, <DerivativeCardKeywords_58:\"Samimi Dostlar\">, <DerivativeCardKeywords_59:\"Huzurlu Bir Yaşam\">.\n\"Sıcak Bir Aile\": 2 Arithmetica kazan.\n\"Samimi Dostlar\": Tüm düşmanlara 1 yığın Semptom: Zayıflık ve Savunmasız uygula.\n\"Huzurlu Bir Yaşam\": 2 kart Çekme."
  },
  LanguageConfig_Resonance_Group_Desc_Railway_CN = {
    Text = "Doldurulacak"
  },
  LanguageConfig_Resonance_Group_Desc_SEWD_CN = {
    Text = "\"Arzu\" Olayı rastgele bir Günahkâr Kalıntı veya Altın Kalıntı verir; \"Tevbe\" Olayı bir Günahkâr Kalıntıyı Lütuflanmış Kalıntıya arındırır; \"Kurtuluş\" Olayı bir Semptom kartını silerek ödüller kazanmanı sağlar."
  },
  LanguageConfig_Resonance_Group_Desc_Wangda_CN = {
    Text = "\"Gizli Vekâlet Emri\" adlı Rezonans Olayında \"Fon Edin\" seçeneğini seçmek, 25 Kara Mühür ve rastgele bir Gümüş Kalıntı kazandırır."
  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "\"Henüz Yitmeyen Bilinç\" adlı Rezonans Olayında destesine bir \"Yedek Beyin Tankı\" karıştır. \"Yedek Beyin Tankı\", daha önce kullanılmış kartları geçici olarak depolayabilir ve duruma göre onları eline alıp almamaya sen karar verebilirsin."
  },
  LanguageConfig_Resonance_Group_Desc_x2_CN = {
    Text = "\"Ruh Göçü\" Olayında bir Uyanan seç ve onu \"Böceksiler\"e dönüştür.\n\"Böceksiler\" %50 artırılmış Aliemus Dolumu ve Keyflare Dolumu kazanır, tüm Komut Kartlarının Arithmetica Maliyeti -1’dir, ancak oynandıklarında Tüketilirler."
  },
  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "\"Ziyafet Öncesi Ritüel\" etkinliğinde, destesine 1 adet \"Ruh Bayramı Özel Karışımı\" yerleştir.\n\"Ruh Bayramı Özel Karışımı\": Arithmetica Maliyeti 1. Tüm Uyananların Krit. Oranı ve Krit. Hasarını Geçici olarak %10 artırır. \"Ruh Bayramı Özel Karışımı\" oynandıktan sonra, bu savaşa özel kalıcı bir etki vermek için içine 1 malzeme yerleştir!"
  },
  LanguageConfig_Resonance_Group_Desc_x4_CN = {
    Text = "\"Murphy'nin İllüzyonu\" etkinliğinde, desteye 3 \"Döngünün Yansıması\" yerleştir.\n\"Döngünün Yansıması\" oynandığında, serbest bırakmak için bir \"Anımsama Etkisi\" keşfet, Tüket. Artçı Sarsıntı: Tüm Uyananlar 5 Aliemus kazanır."
  },
  LanguageConfig_Resonance_Group_Desc_x5_CN = {
    Text = "Geçici Metin, Astral Bölüm 5 için Rezonans İşlevi Açıklaması."
  },
  LanguageConfig_Resonance_Group_Desc_x6_CN = {
    Text = "Yer Tutucu Metin, Yıldız Bölümü altı Rezonans özelliği açıklaması."
