  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:Işıksız Diyar>\nIşıksız Diyar, yüksek zorlukta aşamalardan oluşur. Bu aşamaları temizlemek zengin ödüller kazandırır. Ayrıca, biriken yıldız dereceleri ek ödüller sağlar.\n\n<Title:Soruşturma Gereksinimleri>\nIşıksız Diyar’daki aşamalar, soruşturma için belirli diyarlar ve belirli sayıda Uyanan gerektirebilir. Koruyucular, aşama ayrıntıları ve takım kurulum arayüzünde ayrıntıları kontrol edip takımları yapılandırabilir.\n\n<Title:Başlangıç Kalıntısı>\nIşıksız Diyar’daki aşamalar, yalnızca mevcut aşamada etkili olan benzersiz Kalıntılar içerir. Kalıntı etkilerinin doğru kullanımı, soruşturmaya kayda değer ölçüde yardımcı olacaktır."
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
