  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "Her turun başında, <CardKeyWord:Embriyo Füzyonu> +20 (kaybedilen Cana göre artar, en fazla 40). Limite ulaşıldığında, Elinize 1 <CardKeyWord:\"Embriyo\"> yerleştirilir.\nCaro Diyarının \"Taşkınlık\" etkisi <CardKeyWord:\"Embriyo\"> tüketerek <CardKeyWord:Yutma> Etkisini tetikler. Her turda ilk Yutma sonrasında, Maksimum canın %2'si kadar Kalkan ve Maksimum canın %1'i kadar Geçici GÜÇ kazanılır. (Kaybedilen Cana göre artar, en fazla 2 katına kadar)"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "Kızıl Kurban"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "\nKaos Alanı Uyandırıcıları, Âlem sınırlarını aşarak diğer Âlem Uyandırıcılarıyla aynı takımda yer alabilir.\nHerhangi bir takım dizilişinde bir Kaos Alanı Uyandırıcısı varsa, ayrıca %100 Ölüm Direnci kazanır.\nTur sonunda ve \"Yüceliş\" serbest bırakıldıktan sonra, <CardKeyWord:Anahtarparıltısı> +50."
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
