  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "Her turda oynanan ilk Komut Kartı, geçici olarak <CardKeyWord:Ultra Diyar> içinde kopyalanır ve Sıçrama etkisini tetikler.\nUltra Diyar sınırına ulaştığında, fazladan bir Ultra Tur kazanırsın. Bu turda hiç kart çekilmez, ancak Ultra Diyar’daki tüm kartlar eline eklenir. Ultra Tur, tüm Sıçrama etkilerini tetikleyebilir."
