  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "Savaşın başında 1 Dokunaç üret; bu Dokunaç, tur sonunda ön saftaki düşmanlara saldırır.\nHer Yüceliş, tur sonunda fazladan bir Dokunaç Saldırısı tetikler.\nHer 3 GÜÇ, Dokunaç Hasarı’nı 1 artırır; 3 GÜÇ kaybetmek Dokunaç Hasarı’nı 1 azaltır."
