  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Yukarıdaki kozmosa bakmaya cüret etme. İçindeki Uçurum’a bakmaya da cüret etme."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Bu dünyada tek erdem, sofraya oturmaktır."
