  LanguageConfig_StorylineGuide_13_CN = {
    Text = "Sınırsız Rüya’da yanıt yok. Uyanma vakti geldi."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Kader sahnesinde, oynadığımız rolleri asla biz seçmeyiz."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "Ey Gezginler, o karlı geceye usulca adım atın. Boşalmış iradelerin zirvesinde, büyük bir rüyanın sonuna tanıklık edesiniz."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Ana istatistik, Krit. Oranı, Krit. Hasar, Anahtar Parıltısı Yenilenme Seviyesi veya Aliemus Dolum Seviyesi arasından rastgele seçilir."
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Ana istatistik, Krit. Oranı, Krit. Hasar, Anahtar Parıltısı Yenilenme Seviyesi veya Aliemus Dolum Seviyesi arasından rastgele seçilir."
