  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Londinium’un hain gece sislerine adım at, Koruyucu. Fitil Yolu’n, burada başlıyor."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Ana istatistik, Krit. Oranı, Krit. Hasar, Anahtar Parıltısı Yenilenme Seviyesi veya Aliemus Dolum Seviyesi arasından rastgele seçilir."
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Sanatçılar, deliler, zahitler, ahmaklar... Bu şehir senin galerindir. İşte burada, hikâyelerinin eşiğinde, balmumundan suretler senin Varış’ını arzular."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Rye’ın karları kıyımdan tiksinir. O seni bekliyor, yalnızca bir takas arayarak. En çok arzuladığın Sır’ları sunuyor sana—bedeli daima zalim, ama daima adil."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Hatırla. Hafıza için savaş; Hafıza için öl. O, hem ilahimiz hem mezar taşımızdır. Hafıza’nın ötesinde, bize ait hiçbir şey yok."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Yıldızlar düşmeden önce, denize dua ederdik: nazik dalga bizi Hafif Uyku’ya taşısın. Beyaz Kuş Diyarı’nın Kucaklayış’ına dönelim, hiç bitmeyen bir Rüya’da kaybolalım."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Şimdi İlahi’yi söyle—kadim Kral, Taht’ına yeniden nazar eder. Kutsal buyruğu, İlahi Âlem’i sahici imanın her ruhuna getirir."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Dinle, dua et, Çağrı yap, Çoğalma’ya izin ver. En yüce ideallere ve en aşağılık arzulara boyun eğ. Anne’nin adıyla, O Kaos ve korku içinde de Tahammül eder."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "Ebedî Fener yakıldı. Solgun ışığı, son durağına giden Fitil Yolu’nu aydınlatıyor."
  },
