  LanguageConfig_Task_Appoint_Rules_CN = {
    Text = "<Title:[Assignment Rules]>\nKoruyucular, Uyananları Soruşturma ya da Araştırma görevlerine atayabilir ve tamamlandığında karşılık gelen ödülleri kazanabilir.\nBir görevin seviyesi gereksinimlerini karşılayan toplam atama seviyesi sağlandığında sevk işlemi başarılı olur. Her görev için aynı anda en fazla 4 Uyanan atanabilir.\nGörev gereksiniminden her 20 seviye fazla için ek bir ödül verilir.\nHer Uyanan aynı anda yalnızca bir görevi üstlenebilir. Bir görevi iptal etmek, Uyananı hızla serbest bırakır ancak o göreve ait ödüllerden feragat edilmesine yol açar.\nKoruyucu Seviyesi 20/30/40/50/60’a ulaştığında, atanabilir görev sayısı 1 artar.\nNot: Köken formundaki Uyananlar görevlere atanamaz."
