  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Ahit Bağlama>\nKoruyucular artık Ahitleri Uyandırıcılara bağlayabilir.\nHer Uyandırıcının 6 bağlama yuvası vardır (her yuvaya bir Ahit).\nBağlandıktan sonra, Ahitin birincil niteliği %50 artırılır.\nBağlı Ahitler Envanterinizde veya Simya sisteminde görünmez.\nBir Uyandırıcının kadro veya Destek yuvasında donatılmış Ahiti yoksa, bağlı Ahiti otomatik olarak donatılır.\nBağlı bir Ahiti yükseltmek bağını çözmez; güçlendirilmiş nitelikler otomatik olarak güncellenir.\n\n<Title:Ahit Bağını Çözme>\nBir bağı değiştirmek veya kaldırmak için Ahit Bağlama ekranındaki bağı çözme seçeneğini kullanın.\nTek bir yuvanın bağını çözmek, aynı türden 10 Ahit gerektirir (herhangi bir yuva konumu maliyet olarak kullanılabilir)."
  },
