  LanguageConfig_TrinketConversionReplace_CN = {Text = "Değiştir"},
  LanguageConfig_TrinketConversionRuleTitle_CN = {Text = "Kurallar"},
  LanguageConfig_TrinketConversionRule_CN = {
    Text = "<Title:Transkripsiyon>\nTranskripsiyon, Ahit Alt İstatistiklerinin türünü ve değerini değiştirebilir; Ana İstatistiğin türü ve değeri üzerinde hiçbir etkisi yoktur.\nTranskripsiyon sırasında, Alt İstatistik türleri Ana İstatistikle çakışabilir ve Alt İstatistik türleri birbirleriyle de çakışabilir.\nTranskripsiyon sırasında, Alt İstatistikler değerlerinde farklı güçlerde artışlar alacaktır.\nAhit Transkripsiyonu kilidi açıldıktan sonra, Koruyucu tarafından yeni elde edilen tüm Ahitler, bir kez olmak üzere otomatik ve ücretsiz biçimde transkribe edilecektir.\n\n<Title:Kilitleme>\nTranskripsiyon sırasında belirli Alt İstatistiklerin korunması gerekiyorsa, Alt İstatistiğin yanındaki kilit düğmesine tıklayarak onu kilitleyebilirsin; kilitli Alt İstatistiklerin türleri ve değerleri transkripsiyon süresince korunacaktır.\nAynı anda en fazla iki Alt İstatistik kilitlenebilir.\nBir Alt İstatistiği kilitlemek, ek olarak \"Ahit Kalıntı Nüsha\"*20 maliyeti gerektirir; iki Alt İstatistiği kilitlemek ise ek olarak \"Anı Tüy Kalemi\"*10 maliyeti gerektirir.\nTek bir niteliği kilitlemeyi seçtiğinde, \"Kalıntıları Tamamlamak için Anı Tüy Kalemlerini Tüket\" seçeneğini işaretleyebilirsin; işaretlenirse, mevcut \"Ahit Kalıntı Nüsha\" yetersiz olduğunda, transkripsiyona devam etmek için karşılık gelen sayıda Anı Tüy Kalemi otomatik olarak tüketilecektir."
  },
  LanguageConfig_TrinketConversion_CN = {
    Text = "Transkripsiyon"
  },
  LanguageConfig_TrinketCopyRules_CN = {
    Text = "1. Yasak Ahitname içindeki sahneleri temizledikten sonra bir Ahit elde edebilirsin!\n2. Farklı önerilen seviyelere sahip sahneler, farklı miktarlarda Ahit verir.\n Önerilen seviyesi 25 olan bir sahne 1 Ahit verir.\n Önerilen seviyesi 35 olan bir sahne 2 Ahit verir.\n Önerilen seviyesi 45 olan bir sahne 3 Ahit verir.\n3. Sahne meydan okumasını tamamladıktan sonra Yeniden Canlandırma kilidini açarsın; bu, o sahnenin görev ödüllerini anında almanı sağlar. Her Yeniden Canlandırma, bir Soruşturma için gereken Menofin miktarına eşdeğer Menofin tüketir.\n4. Soruşturma Olayı’nın her bir bölümünü tamamladığında, bir Ahit sahnesi açılır.\n5. Yüksek zorlukta bir sahneyi üç yıldızla tamamlarsan, daha düşük zorluktaki sahnelerin ilerleyişi otomatik olarak üç yıldızla tamamlanmış olarak işaretlenir."
